// Which control renders a value: read from its JSON schema (generated by schemars, inlined),
// with the name as a hint for colours; a path names its native dialog with `x-input`
// (`file` or `folder`, RB-080-20), a free string may suggest values with `x-options`, and a
// list of `enum` strings is a multi-select. A list or a map whose `x-options` names a source the
// core fills at runtime (`plugins`, `check-rules`, RB-080-72) is a pick list of those values by
// name, and a map whose values are a closed choice is a list of entry and choice. A schema the
// window has no control for falls back to a JSON editor, so every key stays editable.

import type { JsonValue, PathKind } from '../ipc/protocol';
import type { JsonSchema } from './schema';

export type FieldKind =
  | 'boolean'
  | 'integer'
  | 'number'
  | 'string'
  | 'path'
  | 'color'
  | 'enum'
  | 'multiEnum'
  | 'pickList'
  | 'choiceMap'
  | 'stringList'
  | 'objectList'
  | 'object'
  | 'objectMap'
  | 'json';

export interface EnumOption {
  value: JsonValue;
  label: string;
}

function isSchema(value: unknown): value is JsonSchema {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function types(schema: JsonSchema): string[] {
  const type = schema.type;
  if (typeof type === 'string') {
    return [type];
  }
  return Array.isArray(type) ? type.filter((t): t is string => typeof t === 'string') : [];
}

function isNullBranch(branch: unknown): boolean {
  return isSchema(branch) && branch.type === 'null';
}

/** Whether the schema allows `null` (unset). */
export function isNullable(schema: JsonSchema): boolean {
  if (types(schema).includes('null')) {
    return true;
  }
  const branches = schema.anyOf ?? schema.oneOf;
  return Array.isArray(branches) && branches.some(isNullBranch);
}

/** The schema without its `null` alternative: `["string", "null"]` -> `string`, an `anyOf`
 * of one value and `null` -> that value's schema. */
export function baseSchema(schema: JsonSchema): JsonSchema {
  const plain = types(schema).filter((type) => type !== 'null');
  if (plain.length === 1 && types(schema).length > 1) {
    return { ...schema, type: plain[0] ?? null };
  }
  const branches = schema.anyOf;
  if (Array.isArray(branches)) {
    const real = branches.filter((branch) => !isNullBranch(branch));
    const [only] = real;
    if (real.length === 1 && isSchema(only)) {
      return { ...only, description: schema.description ?? only.description ?? null };
    }
  }
  return schema;
}

/** The allowed values of an `enum` or a `oneOf` of constants; `null` when the schema is none. */
export function enumOptions(schema: JsonSchema): EnumOption[] | null {
  const base = baseSchema(schema);
  if (Array.isArray(base.enum)) {
    return base.enum.map((value) => ({ value, label: String(value) }));
  }
  const branches = base.oneOf;
  if (Array.isArray(branches) && branches.length > 0) {
    const consts = branches.filter(
      (branch): branch is JsonSchema => isSchema(branch) && branch.const !== undefined,
    );
    if (consts.length === branches.length) {
      return consts.map((branch) => ({ value: branch.const ?? null, label: String(branch.const) }));
    }
  }
  return null;
}

/** The native dialog that fills a string (`x-input`); `null` for a plain string. */
export function pathInputOf(schema: JsonSchema): PathKind | null {
  const input = baseSchema(schema)['x-input'];
  return input === 'file' || input === 'folder' ? input : null;
}

/** The values a free string suggests (`x-options`); empty when it suggests none. */
export function optionsOf(schema: JsonSchema): string[] {
  const options = baseSchema(schema)['x-options'];
  return Array.isArray(options) ? options.filter((option): option is string => typeof option === 'string') : [];
}

/** The values `"dynamic"` means on a path; any other text in `x-options` names a source. */
const DYNAMIC = 'dynamic';

/** The source of known values the core fills in at runtime (`x-options: "plugins"`); `null`
 * when the schema names none. */
export function sourceOf(schema: JsonSchema): string | null {
  const options = baseSchema(schema)['x-options'];
  return typeof options === 'string' && options !== DYNAMIC ? options : null;
}

/** The control for a value of `schema`; `name` (the key or field name) hints colours. */
export function kindOf(schema: JsonSchema, name = ''): FieldKind {
  if (enumOptions(schema) !== null) {
    return 'enum';
  }
  const base = baseSchema(schema);
  const [type] = types(base);
  const leaf = name.split('.').pop() ?? '';
  switch (type) {
    case 'boolean':
      return 'boolean';
    case 'integer':
      return 'integer';
    case 'number':
      return 'number';
    case 'string':
      if (pathInputOf(base) !== null) {
        return 'path';
      }
      return /colou?r$/i.test(leaf) || base.format === 'color' ? 'color' : 'string';
    case 'array': {
      const items = isSchema(base.items) ? base.items : {};
      const itemKind = kindOf(items);
      if (itemKind === 'enum') {
        return 'multiEnum';
      }
      if (itemKind === 'string' && sourceOf(base) !== null) {
        return 'pickList';
      }
      if (itemKind === 'string' || itemKind === 'path') {
        return 'stringList';
      }
      return itemKind === 'object' ? 'objectList' : 'json';
    }
    case 'object':
      if (isSchema(base.properties)) {
        return 'object';
      }
      if (!isSchema(base.additionalProperties)) {
        return 'json';
      }
      // A map of named objects (the layout presets): one entry per name, like a list. A map to a
      // closed choice (the rule overrides): one line per entry, its name and the choice.
      switch (kindOf(base.additionalProperties)) {
        case 'object':
          return 'objectMap';
        case 'enum':
          return 'choiceMap';
        default:
          return 'json';
      }
    default:
      return 'json';
  }
}

/** The named fields of an object schema, in schema order. */
export function propertiesOf(schema: JsonSchema): [string, JsonSchema][] {
  const properties = baseSchema(schema).properties;
  if (!isSchema(properties)) {
    return [];
  }
  return Object.entries(properties).filter((entry): entry is [string, JsonSchema] => isSchema(entry[1]));
}

/** The schema of a map's values (`additionalProperties`). */
export function mapValuesOf(schema: JsonSchema): JsonSchema {
  const values = baseSchema(schema).additionalProperties;
  return isSchema(values) ? values : {};
}

/** The schema of a list's items. */
export function itemsOf(schema: JsonSchema): JsonSchema {
  const items = baseSchema(schema).items;
  return isSchema(items) ? items : {};
}

/** A new, empty item for a list of `items`: the required fields with a neutral value. */
export function newItem(items: JsonSchema): JsonValue {
  const kind = kindOf(items);
  if (kind !== 'object') {
    return kind === 'boolean' ? false : kind === 'integer' || kind === 'number' ? 0 : '';
  }
  const required = Array.isArray(items.required) ? items.required : [];
  const item: { [key: string]: JsonValue } = {};
  for (const [name, field] of propertiesOf(items)) {
    if (required.includes(name)) {
      item[name] = newItem(field);
    }
  }
  return item;
}

/** The numeric bounds of a number schema. */
export function boundsOf(schema: JsonSchema): { min?: number; max?: number } {
  const base = baseSchema(schema);
  return {
    ...(typeof base.minimum === 'number' ? { min: base.minimum } : {}),
    ...(typeof base.maximum === 'number' ? { max: base.maximum } : {}),
  };
}
